class Loader:
    def read(self, path):
        with open(path) as fh:
            for line in fh:
                if line.startswith('#'):
                    continue
                yield line

def merge(a, b):
    out = {}
    for key in a:
        if key in b:
            out[key] = a[key] + b[key]
        else:
            out[key] = a[key]
    return out

def save(self):
    try:
        self.conn.commit()
    except Exception:
        self.conn.rollback()
        raise

def walk(node):
    while node is not None:
        if node.left:
            walk(node.left)
        node = node.right

class Server:
    def handle(self, req):
        if req.method == 'GET':
            return self.get(req)
        elif req.method == 'POST':
            return self.post(req)

